                return _clip(handler(**args))
            except (
                PathEscape, EditError, GraphError, SuiteTimeout, NoJunit,
                KeyError, TypeError, ValueError, OSError,
            ) as exc:
                return ToolOutput(self._scrub(f"error: {type(exc).__name__}: {exc}"), True)
